window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-440091d1df450812"]={"versions": [{"id": "FIG-440091d1df450812", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der E2E-Prüffunktion <code>E2E_P22Check</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 22). Es spezifiziert das dynamische Verhalten der Empfängerseite zur Integritäts- und Konsistenzprüfung empfangener Datenpakete.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionsschnittstelle / Einstieg</strong>: <code>E2E_P22Check(Config, State, Data, Length)</code></li>\n<li>Parameter: <code>Config</code> (Profil-Konfigurationsstruktur), <code>State</code> (Zustandsstruktur der Prüffunktion), <code>Data</code> (Zeiger auf das empfangene Daten-Array), <code>Length</code> (Länge der empfangenen Daten)</li>\n<li><strong>Aktivitätsknoten / Sub-Aktivitäten</strong>:</li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li><strong>Entscheidungsknoten</strong>: Verzweigung anhand der Bedingung <code>NewDataAvailable == TRUE</code></li>\n<li><strong>Endknoten / Rückgabewerte</strong>:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code> (bei Null-Zeigern)</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code> (bei fehlerhaften Eingabeparametern)</li>\n<li><code>return E2E_E_OK</code> (nach regulärem Durchlauf der Prüfschritte)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Ausführung beginnt mit dem Aufruf von <code>E2E_P22Check(Config, State, Data, Length)</code>.</li>\n<li>Erste Aktion ist <code>Verify inputs of the check function</code>. Schlägt die Validierung fehl, verzweigt der Ablauf direkt zu Endknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[null input]</code> Terminierung mit Rückgabe von <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei <code>[wrong input]</code> Terminierung mit Rückgabe von <code>E2E_E_INPUTERR_WRONG</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[input ok]</code> erfolgt die Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist die Bedingung erfüllt (Default-Pfad nach unten), werden sequenziell ausgeführt: <code>Read Counter</code> -> <code>Read CRC</code> -> <code>Compute CRC</code> -> <code>Do checks</code>.</li>\n<li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>), werden das Lesen von Counter und CRC sowie die CRC-Berechnung übersprungen und die Verzweigung führt direkt zur Aktion <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss von <code>Do checks</code> terminiert die Funktion regulär mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensvorschrift für die E2E-Profil-22-Implementierung gemäß Anforderung <code>[PRS_E2E_00534]</code>. Für Implementierer ist sicherzustellen, dass die Eingabeparameter vor jeglicher Datenverarbeitung strikt validiert werden. Liegen keine neuen Daten vor (<code>NewDataAvailable == FALSE</code>), darf kein CRC neu berechnet und keine Datenwerte ausgelesen werden; stattdessen ist direkt die Zustandsüberprüfung (<code>Do checks</code>) auszuführen, um Timeout- oder Wiederholungszustände im E2E-Status korrekt fortzuschreiben.</p>"}, {"id": "FIG-189cbd62541a706b", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der E2E-Prüffunktion <code>E2E_P22Check</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 22). Es spezifiziert das dynamische Verhalten der Empfängerseite zur Integritäts- und Konsistenzprüfung empfangener Datenpakete.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionsschnittstelle / Einstieg</strong>: <code>E2E_P22Check(Config, State, Data, Length)</code></li>\n<li>Parameter: <code>Config</code> (Profil-Konfigurationsstruktur), <code>State</code> (Zustandsstruktur der Prüffunktion), <code>Data</code> (Zeiger auf das empfangene Daten-Array), <code>Length</code> (Länge der empfangenen Daten)</li>\n<li><strong>Aktivitätsknoten / Sub-Aktivitäten</strong>:</li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li><strong>Entscheidungsknoten</strong>: Verzweigung anhand der Bedingung <code>NewDataAvailable == TRUE</code></li>\n<li><strong>Endknoten / Rückgabewerte</strong>:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code> (bei Null-Zeigern)</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code> (bei fehlerhaften Eingabeparametern)</li>\n<li><code>return E2E_E_OK</code> (nach regulärem Durchlauf der Prüfschritte)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Ausführung beginnt mit dem Aufruf von <code>E2E_P22Check(Config, State, Data, Length)</code>.</li>\n<li>Erste Aktion ist <code>Verify inputs of the check function</code>. Schlägt die Validierung fehl, verzweigt der Ablauf direkt zu Endknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[null input]</code> Terminierung mit Rückgabe von <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei <code>[wrong input]</code> Terminierung mit Rückgabe von <code>E2E_E_INPUTERR_WRONG</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[input ok]</code> erfolgt die Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist die Bedingung erfüllt (Default-Pfad nach unten), werden sequenziell ausgeführt: <code>Read Counter</code> -> <code>Read CRC</code> -> <code>Compute CRC</code> -> <code>Do checks</code>.</li>\n<li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>), werden das Lesen von Counter und CRC sowie die CRC-Berechnung übersprungen und die Verzweigung führt direkt zur Aktion <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss von <code>Do checks</code> terminiert die Funktion regulär mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensvorschrift für die E2E-Profil-22-Implementierung gemäß Anforderung <code>[PRS_E2E_00534]</code>. Für Implementierer ist sicherzustellen, dass die Eingabeparameter vor jeglicher Datenverarbeitung strikt validiert werden. Liegen keine neuen Daten vor (<code>NewDataAvailable == FALSE</code>), darf kein CRC neu berechnet und keine Datenwerte ausgelesen werden; stattdessen ist direkt die Zustandsüberprüfung (<code>Do checks</code>) auszuführen, um Timeout- oder Wiederholungszustände im E2E-Status korrekt fortzuschreiben.</p>"}, {"id": "FIG-f1f02fd1a9232e17", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der E2E-Prüffunktion <code>E2E_P22Check</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 22). Es spezifiziert das dynamische Verhalten der Empfängerseite zur Integritäts- und Konsistenzprüfung empfangener Datenpakete.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionsschnittstelle / Einstieg</strong>: <code>E2E_P22Check(Config, State, Data, Length)</code></li>\n<li>Parameter: <code>Config</code> (Profil-Konfigurationsstruktur), <code>State</code> (Zustandsstruktur der Prüffunktion), <code>Data</code> (Zeiger auf das empfangene Daten-Array), <code>Length</code> (Länge der empfangenen Daten)</li>\n<li><strong>Aktivitätsknoten / Sub-Aktivitäten</strong>:</li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li><strong>Entscheidungsknoten</strong>: Verzweigung anhand der Bedingung <code>NewDataAvailable == TRUE</code></li>\n<li><strong>Endknoten / Rückgabewerte</strong>:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code> (bei Null-Zeigern)</li>\n<li><code>return E2E_E_INPUTERR_WRONG</code> (bei fehlerhaften Eingabeparametern)</li>\n<li><code>return E2E_E_OK</code> (nach regulärem Durchlauf der Prüfschritte)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Ausführung beginnt mit dem Aufruf von <code>E2E_P22Check(Config, State, Data, Length)</code>.</li>\n<li>Erste Aktion ist <code>Verify inputs of the check function</code>. Schlägt die Validierung fehl, verzweigt der Ablauf direkt zu Endknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[null input]</code> Terminierung mit Rückgabe von <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei <code>[wrong input]</code> Terminierung mit Rückgabe von <code>E2E_E_INPUTERR_WRONG</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[input ok]</code> erfolgt die Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist die Bedingung erfüllt (Default-Pfad nach unten), werden sequenziell ausgeführt: <code>Read Counter</code> -> <code>Read CRC</code> -> <code>Compute CRC</code> -> <code>Do checks</code>.</li>\n<li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>), werden das Lesen von Counter und CRC sowie die CRC-Berechnung übersprungen und die Verzweigung führt direkt zur Aktion <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss von <code>Do checks</code> terminiert die Funktion regulär mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensvorschrift für die E2E-Profil-22-Implementierung gemäß Anforderung <code>[PRS_E2E_00534]</code>. Für Implementierer ist sicherzustellen, dass die Eingabeparameter vor jeglicher Datenverarbeitung strikt validiert werden. Liegen keine neuen Daten vor (<code>NewDataAvailable == FALSE</code>), darf kein CRC neu berechnet und keine Datenwerte ausgelesen werden; stattdessen ist direkt die Zustandsüberprüfung (<code>Do checks</code>) auszuführen, um Timeout- oder Wiederholungszustände im E2E-Status korrekt fortzuschreiben.</p>"}], "trans": [{"from": "FIG-440091d1df450812", "to": "FIG-189cbd62541a706b", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Beschriftung am Startknoten: Signatur umgebrochen (<code>E2E_P22Check(Config, State, Data,</code> / <code>Length)</code> statt einzeilig).</li>\n<li>Beschriftung der Verzweigung <code>[input ok]</code>: Text zweizeilig umgebrochen (<code>[input</code> / <code>ok]</code>).</li>\n<li>Beschriftungen der drei Ausgangskanten (<code>return ...</code>) am unteren Bildrand sind durch Beschnitt bzw. Skalierung verkürzt dargestellt.</li>\n</ul>"}, {"from": "FIG-189cbd62541a706b", "to": "FIG-f1f02fd1a9232e17", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
